def parse_number(text, decimal_comma=False):
    text = text.strip()
    if decimal_comma:
        text = text.replace(".", "").replace(",", ".")
    else:
        text = text.replace(",", "")
    return Decimal(text)


def parse_weight(text, unit, decimal_comma=False):
    text = (text or "").strip()
    match = re.match(r"^(.*?)\s*(kg|g|lb|oz)$", text, re.I)
    if match:
        text, unit = match.group(1), match.group(2).lower()
    try:
        return parse_number(text, decimal_comma) * KG[unit]
    except (InvalidOperation, KeyError):
        return None


def to_date(value, form):
    value = value.strip()
    if not value:
        return None
    if re.search(r"\d[T ]\d{1,2}:\d\d", value):
        stamp = datetime.fromisoformat(value.replace(" ", "T", 1))
        if stamp.tzinfo is not None:
            stamp = stamp.astimezone(timezone.utc)
        return stamp.date()
    match = re.match(r"^(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})$", value)
    if match:
        return date(int(match.group(3)), MONTHS[match.group(2).lower()], int(match.group(1)))
    form = (form or "iso").strip()
    upper = form.upper()
    nums = re.findall(r"\d+", value)
    if upper == "SERIAL" or (len(nums) == 1 and len(value) <= 6 and upper == "SERIAL"):
        return date(1899, 12, 30) + timedelta(days=int(float(value)))
    if upper in ("ISO", "YMD", "YYYY-MM-DD"):
        return date(int(nums[0]), int(nums[1]), int(nums[2]))
    if upper in ("DMY", "DD-MM-YYYY", "DD.MM.YYYY", "DD/MM/YYYY"):
        return date(int(nums[2]), int(nums[1]), int(nums[0]))
    if upper in ("MM/DD/YYYY", "MDY"):
        return date(int(nums[2]), int(nums[0]), int(nums[1]))
    if upper == "YYYYMMDD":
        return date(int(value[:4]), int(value[4:6]), int(value[6:8]))
    if upper == "YYYYDDD":
        return date(int(value[:4]), 1, 1) + timedelta(days=int(value[4:7]) - 1)
    return date(int(nums[0]), int(nums[1]), int(nums[2]))


def logical_lines(text):
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    return text.split("\n")


def csv_records(text, depot):
    """Yield ('comment', line) or ('row', fields) in file order."""
    delim = DELIM[depot]
    lines = logical_lines(text)
    index = 0
    while index < len(lines):
        line = lines[index]
        index += 1
        if not line.strip():
            continue
        if line.startswith("#"):
            yield "comment", line
            continue
        if depot in QUOTED:
            while line.count('"') % 2 == 1 and index < len(lines):
                line += "\n" + lines[index]
                index += 1
            row = next(csv.reader([line], delimiter=delim))
        else:
            row = line.split(delim)
        yield "row", row


def directive(line):
    match = re.match(r"^#\s*([^:]+?)\s*:\s*(.*?)\s*$", line)
    if not match:
        return None
    return match.group(1).strip().lower(), match.group(2)


def parse_delimited(text, depot):
    cols = COLUMNS[depot]
    roles = FIELDS[depot]
    seq = None
    form = BASE_DATE[depot]
    unit = BASE_UNIT[depot]
    decimal_comma = depot == "west"
    header = None
    records = []
    for kind, item in csv_records(text, depot):
        if kind == "comment":
            parsed = directive(item)
            if depot == "harbor":
                match = re.match(r"^#harbor export seq=(\d+)", item)
                if match and seq is None:
                    seq = int(match.group(1))
            if not parsed:
                continue
            name, value = parsed
            if name == "seq":
                if seq is None:
                    seq = int(value)
            elif name in ("dates", "date format", "date"):
                form = value
            elif name in ("unit", "weight unit"):
                found = parse_unit(re.split(r"[\s(]", value.strip())[0])
                if found:
                    unit = found
                if "decimal comma" in value:
                    decimal_comma = True
            continue
        row = item
        stripped = [field.strip().lower() for field in row]
        if stripped and all(field in cols for field in stripped):
            header = stripped
            continue
        if header is None:
            continue
        own_unit = None
        weight_idx = header.index(roles["weight"]) if roles["weight"] in header else None
        if len(row) == len(header) + 1 and weight_idx is not None:
            own_unit = parse_unit(row[weight_idx + 1])
            if own_unit:
                row = row[:weight_idx + 1] + row[weight_idx + 2:]
        if len(row) != len(header):
            continue
        data = dict(zip(header, row))
        if depot == "east" and data.get("id", "").strip().upper() == "TOTAL":
            continue
        number = id_number(data.get(roles["id"]))
        if number is None:
            continue
        rtype = rec_type(data.get(roles["type"]))
        record = None
        if rtype != "void":
            column_unit = None
            wcol = roles["weight"]
            match = re.search(r"_(kg|g|lb|oz)$", wcol)
            if match:
                column_unit = match.group(1)
            use_unit = column_unit or own_unit or unit
            weight = parse_weight(data.get(wcol), use_unit, decimal_comma)
            when = to_date(data.get(roles["ship"], ""), form)
            status = data.get(roles["status"], "")
            status = HARBOR_STATUS.get(status.strip().upper(), status) if depot == "harbor" else status
            record = (when, weight, norm_status(status))
        records.append((rtype, number, record))
    return seq, records


def parse_fixed(text):
    seq = None
    layout = None
    records = []
    lengths = {"FW1": 42, "FW2": 43, "FW3": 41}
    for line in logical_lines(text):
        if not line.strip(" \f"):
            continue
        if line.startswith("\f") or "SHIPMENT LISTING" in line:
            continue
        if line.startswith("#"):
            match = re.match(r"^#LAYOUT\s+(\S+)", line)
            if match:
                layout = match.group(1)
                continue
            match = re.match(r"^#SEQ\s+(\d+)", line)
            if match and seq is None:
                seq = int(match.group(1))
            continue
        name = layout
        if len(line) != lengths.get(layout):
            for key, size in lengths.items():
                if size == len(line):
                    name = key
        if name == "FW1":
            id_, typ, ship, wt, st = line[0:9], line[9], line[10:17], line[17:25], line[25]
            kg = Decimal(wt or 0) * KG["g"] if wt.strip() else None
            fmt = "YYYYDDD"
        elif name == "FW2":
            typ, id_, ship, wt, st = line[0], line[1:10], line[10:18], line[18:26], line[26]
            kg = Decimal(wt) / 100 if wt.strip() else None
            fmt = "YYYYMMDD"
        elif name == "FW3":
            id_, ship, typ, wt, st = line[0:9], line[9:16], line[16], line[17:24], line[24]
            kg = Decimal(wt) / 10 * KG["lb"] if wt.strip() else None
            fmt = "YYYYDDD"
        else:
            continue
        number = id_number(id_)
        rtype = rec_type(typ)
        record = None
        if rtype != "void":
            record = (to_date(ship, fmt), kg, FW_STATUS.get(st.strip().upper(), ""))
        records.append((rtype, number, record))
    return seq, records


def parse_xml(data):
    root = ET.fromstring(data)
    seq = int(root.get("seq")) if root.get("seq") else None
    root_unit = parse_unit(root.get("weight-unit")) or "kg"
    records = []
    for element in root.iter("shipment"):
        number = id_number(element.get("id"))
        if number is None:
            continue
        rtype = rec_type(element.get("type"))
        record = None
        if rtype != "void":
            weight_el = element.find("weight")
            unit = root_unit
            weight = None
            if weight_el is not None:
                unit = parse_unit(weight_el.get("unit")) or root_unit
                weight = parse_weight(weight_el.text, unit)
            ship = element.get("shipped")
            if ship is None:
                ship_el = element.find("shipped")
                ship = ship_el.text if ship_el is not None else ""
            status_el = element.find("status")
            status = status_el.text if status_el is not None else element.get("status", "")
            record = (to_date(ship or "", "iso"), weight, norm_status(status))
        records.append((rtype, number, record))
    return seq, records


def parse_json(text):
    seq = None
    records = []
    for line in logical_lines(text):
        line = line.strip()
        if not line:
            continue
        value = json.loads(line)
        for obj in value if isinstance(value, list) else [value]:
            if not isinstance(obj, dict):
                continue
            if "meta" in obj and "id" not in obj:
                if seq is None and "seq" in obj["meta"]:
                    seq = int(obj["meta"]["seq"])
                continue
            number = id_number(str(obj.get("id", "")))
            if number is None:
                continue
            rtype = rec_type(obj.get("kind"))
            record = None
            if rtype != "void":
                weight = None
                for key, val in obj.items():
                    match = re.match(r"^weight_(kg|g|lb|oz)$", key, re.I)
                    if match:
                        weight = parse_weight(str(val), match.group(1).lower())
                if weight is None and "weight" in obj:
                    weight = parse_weight(str(obj["weight"]), parse_unit(obj.get("unit")) or "kg")
                record = (to_date(obj.get("shipped_at", ""), "iso"), weight,
                          norm_status(obj.get("status")))
            records.append((rtype, number, record))
    return seq, records


def parse_file(path, depot):
    data = read_bytes(path)
    if depot == "central" or data.lstrip()[:5] == b"<?xml" or data.lstrip()[:7] == b"<export":
        return parse_xml(data)
    text = decode(data)
    if depot == "south":
        return parse_fixed(text)
    if depot == "north":
        return parse_json(text)
    return parse_delimited(text, depot)


def main(data_dir, out_file):
    depot_files = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if os.path.isfile(path):
            depot_files.setdefault(name.split("-")[0], []).append(path)
    corrections = resends = 0
    current_by_depot = {}
    for depot, paths in depot_files.items():
        parsed = []
        for path in paths:
            seq, records = parse_file(path, depot)
            parsed.append((seq if seq is not None else -1, os.path.basename(path), records))
        parsed.sort(key=lambda item: (item[0], item[1]))
        current = {}
        for _, _, records in parsed:
            for rtype, number, record in records:
                if rtype == "new":
                    if number in current:
                        resends += 1
                    else:
                        current[number] = record
                elif rtype == "correction":
                    current[number] = record
                    corrections += 1
                else:
                    current.pop(number, None)
                    corrections += 1
        current_by_depot[depot] = current
    rank = {name: index for index, name in enumerate(ORDER)}
    owners = {}
    for depot, current in current_by_depot.items():
        for number in current:
            owners.setdefault(number, []).append(depot)
    handovers = sum(1 for depots in owners.values() if len(depots) > 1)
    depots_out = {depot: [0, Decimal(0)] for depot in sorted(depot_files)}
    months = {}
    for number, depots in owners.items():
        winner = min(depots, key=lambda name: rank.get(name, len(rank)))
        when, weight, status = current_by_depot[winner][number]
        if not counted(status) or when is None or weight is None:
            continue
        depots_out[winner][0] += 1
        depots_out[winner][1] += weight
        entry = months.setdefault("%04d-%02d" % (when.year, when.month), [0, Decimal(0)])
        entry[0] += 1
        entry[1] += weight

    def fmt(entry):
        return {"shipments": entry[0], "total_kg": float(round(entry[1], 2))}
    result = {
        "depots": {name: fmt(entry) for name, entry in depots_out.items()},
        "months": {key: fmt(months[key]) for key in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as handle:
        json.dump(result, handle, indent=2)
        handle.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
